#include <bits/stdc++.h>
using namespace std;

int n;

int bfs(int a, int b) {
    queue<pair<pair<int, int>, int>> q;
    q.push({{a, b}, 0});

    while (!q.empty()) {
        auto [state, moves] = q.front();
        q.pop();

        int x = state.first;
        int y = state.second;

        if (x == n || y == n)
            return moves;

        long long sum = 1LL * x + y;
        if (sum <= n) {
            q.push({{static_cast<int>(sum), x}, moves + 1});
            q.push({{x, static_cast<int>(sum)}, moves + 1});
        }
    }

    return -1;
}

int main() {
    cin >> n;
    cout << bfs(1, 1);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    if (n == 1) {
        cout << 0;
        return 0;
    }

    long long answer = n - 1;

    for (long long k = 1; k < n; ++k) {
        long long a = n, b = k, steps = 0;

        while (a != b && steps < answer) {
            if (a > b) {
                long long q = (a - 1) / b;
                a -= q * b;
                steps += q;
            } else {
                long long q = (b - 1) / a;
                b -= q * a;
                steps += q;
            }
        }

        if (a == 1 && b == 1)
            answer = min(answer, steps);
    }

    cout << answer;
    return 0;
}

