#include <bits/stdc++.h>
using namespace std;

int n;

int bfs(int a, int b) {
    queue<tuple<int, int, int>> q;
    set<pair<int, int>> visited;

    q.emplace(a, b, 0);
    visited.emplace(a, b);

    while (!q.empty()) {
        auto [x, y, steps] = q.front();
        q.pop();

        if (x == n || y == n)
            return steps;

        pair<int, int> next[] = {{x + y, x}, {x, x + y}};

        for (auto [nx, ny] : next) {
            if (nx <= n && ny <= n && visited.emplace(nx, ny).second)
                q.emplace(nx, ny, steps + 1);
        }
    }

    return -1;
}

int main() {
    cin >> n;
    cout << bfs(1, 1);
    return 0;
}

